import { useState } from 'react';
import type {
  AdminUserAccreditationResponse,
  AccreditationSubmissionItem,
} from '../../../types/accreditation';
import { formatDateTime } from './helpers';

const ACCREDITATION_OVERRIDE_OPTIONS = [
  { value: 'none', label: 'None (reset)' },
  { value: 'approved', label: 'Approved' },
  { value: 'rejected', label: 'Rejected' },
];

export interface AccreditationTabProps {
  accreditationData: AdminUserAccreditationResponse | null;
  userAccreditationStatus?: string;
  userAccreditationVerifiedAt?: string;
  userAccreditationExpiresAt?: string;
  error: string | null;
  onRetry: () => void;
  onOverride: (status: string) => Promise<void>;
  onReview: (
    submissionId: string,
    approved: boolean,
    reviewerNotes?: string,
    rejectionReason?: string
  ) => Promise<void>;
}

export function AccreditationTab({
  accreditationData,
  userAccreditationStatus,
  userAccreditationVerifiedAt,
  userAccreditationExpiresAt,
  error,
  onRetry,
  onOverride,
  onReview,
}: AccreditationTabProps) {
  const [overrideStatus, setOverrideStatus] = useState('none');
  const [overrideInProgress, setOverrideInProgress] = useState(false);
  const [overrideError, setOverrideError] = useState<string | null>(null);
  const [reviewingId, setReviewingId] = useState<string | null>(null);
  const [reviewNotes, setReviewNotes] = useState('');
  const [reviewRejection, setReviewRejection] = useState('');
  const [reviewInProgress, setReviewInProgress] = useState(false);
  const [reviewError, setReviewError] = useState<string | null>(null);

  const effectiveStatus = accreditationData?.status ?? userAccreditationStatus ?? 'none';
  const effectiveVerifiedAt = accreditationData?.verifiedAt ?? userAccreditationVerifiedAt;
  const effectiveExpiresAt = accreditationData?.expiresAt ?? userAccreditationExpiresAt;

  const handleOverride = async () => {
    const confirmed = window.confirm(
      `Override accreditation status to "${overrideStatus}" for this user?`
    );
    if (!confirmed) return;
    setOverrideInProgress(true);
    setOverrideError(null);
    try {
      await onOverride(overrideStatus);
    } catch (err) {
      setOverrideError(err instanceof Error ? err.message : 'Override failed');
    } finally {
      setOverrideInProgress(false);
    }
  };

  const handleReview = async (submissionId: string, approved: boolean) => {
    const label = approved ? 'approve' : 'reject';
    const confirmed = window.confirm(
      `${label.charAt(0).toUpperCase() + label.slice(1)} this submission?`
    );
    if (!confirmed) return;
    setReviewInProgress(true);
    setReviewError(null);
    try {
      await onReview(
        submissionId,
        approved,
        reviewNotes || undefined,
        !approved ? reviewRejection || undefined : undefined
      );
      setReviewingId(null);
      setReviewNotes('');
      setReviewRejection('');
    } catch (err) {
      setReviewError(err instanceof Error ? err.message : 'Review failed');
    } finally {
      setReviewInProgress(false);
    }
  };

  if (error) {
    return (
      <div className="cedros-admin-tab-error">
        <p className="cedros-admin-error-inline">{error}</p>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={onRetry}
        >
          Retry
        </button>
      </div>
    );
  }

  if (!accreditationData && !userAccreditationStatus) {
    return (
      <div className="cedros-admin-tab-loading">
        <span className="cedros-admin-loading-indicator" />
        <span>Loading accreditation data...</span>
      </div>
    );
  }

  return (
    <div className="cedros-accreditation-admin-tab">
      {/* Status summary */}
      <div className="cedros-kyc-admin-tab-summary">
        <div className="cedros-kyc-admin-tab-row">
          <span className="cedros-kyc-admin-tab-label">Status</span>
          <span
            className={`cedros-admin-status-badge cedros-accreditation-status-${effectiveStatus}`}
          >
            {effectiveStatus}
          </span>
        </div>
        {effectiveVerifiedAt && (
          <div className="cedros-kyc-admin-tab-row">
            <span className="cedros-kyc-admin-tab-label">Verified at</span>
            <span>{formatDateTime(effectiveVerifiedAt)}</span>
          </div>
        )}
        {effectiveExpiresAt && (
          <div className="cedros-kyc-admin-tab-row">
            <span className="cedros-kyc-admin-tab-label">Expires at</span>
            <span>{formatDateTime(effectiveExpiresAt)}</span>
          </div>
        )}
      </div>

      {/* Override */}
      <div className="cedros-kyc-admin-override">
        <span className="cedros-kyc-admin-override-label">Override status</span>
        <select
          className="cedros-kyc-admin-override-select"
          value={overrideStatus}
          onChange={(e) => setOverrideStatus(e.target.value)}
          disabled={overrideInProgress}
          aria-label="Select accreditation override status"
        >
          {ACCREDITATION_OVERRIDE_OPTIONS.map((opt) => (
            <option key={opt.value} value={opt.value}>
              {opt.label}
            </option>
          ))}
        </select>
        <button
          type="button"
          className="cedros-button cedros-button-outline cedros-button-sm"
          onClick={handleOverride}
          disabled={overrideInProgress}
        >
          {overrideInProgress ? 'Saving...' : 'Apply Override'}
        </button>
        {overrideError && <p className="cedros-admin-error-inline">{overrideError}</p>}
      </div>

      {/* Submission history */}
      {accreditationData && accreditationData.submissions.length > 0 ? (
        <>
          <div className="cedros-admin-list-table">
            <div className="cedros-admin-list-thead">
              <div className="cedros-admin-list-th">Date</div>
              <div className="cedros-admin-list-th">Method</div>
              <div className="cedros-admin-list-th">Status</div>
              <div className="cedros-admin-list-th">Expires</div>
              <div className="cedros-admin-list-th">Actions</div>
            </div>
            {accreditationData.submissions.map((sub: AccreditationSubmissionItem) => (
              <div key={sub.id} className="cedros-admin-list-row">
                <div className="cedros-admin-list-td">{formatDateTime(sub.createdAt)}</div>
                <div className="cedros-admin-list-td">{sub.method.replace(/_/g, ' ')}</div>
                <div className="cedros-admin-list-td">
                  <span
                    className={`cedros-admin-status-badge cedros-accreditation-status-${sub.status}`}
                  >
                    {sub.status}
                  </span>
                </div>
                <div className="cedros-admin-list-td">
                  {sub.expiresAt ? formatDateTime(sub.expiresAt) : '—'}
                </div>
                <div className="cedros-admin-list-td cedros-admin-list-td-actions">
                  {sub.status === 'pending' && (
                    <button
                      type="button"
                      className="cedros-button cedros-button-outline cedros-button-sm"
                      onClick={() => setReviewingId(reviewingId === sub.id ? null : sub.id)}
                    >
                      Review
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
          {reviewingId && (
            <div className="cedros-accreditation-review-panel">
              <p className="cedros-accreditation-review-title">Review submission</p>
              <label className="cedros-kyc-admin-tab-label" htmlFor="review-notes">
                Reviewer notes (internal)
              </label>
              <input
                id="review-notes"
                type="text"
                className="cedros-input cedros-input-sm"
                value={reviewNotes}
                onChange={(e) => setReviewNotes(e.target.value)}
                placeholder="Optional internal notes"
                disabled={reviewInProgress}
              />
              <label className="cedros-kyc-admin-tab-label" htmlFor="review-rejection">
                Rejection reason (shown to user if rejected)
              </label>
              <input
                id="review-rejection"
                type="text"
                className="cedros-input cedros-input-sm"
                value={reviewRejection}
                onChange={(e) => setReviewRejection(e.target.value)}
                placeholder="Required when rejecting"
                disabled={reviewInProgress}
              />
              <div className="cedros-accreditation-review-actions">
                <button
                  type="button"
                  className="cedros-button cedros-button-outline cedros-button-sm"
                  onClick={() => handleReview(reviewingId, true)}
                  disabled={reviewInProgress}
                >
                  {reviewInProgress ? 'Saving...' : 'Approve'}
                </button>
                <button
                  type="button"
                  className="cedros-button cedros-button-outline cedros-button-sm cedros-admin-btn-danger"
                  onClick={() => handleReview(reviewingId, false)}
                  disabled={reviewInProgress || !reviewRejection.trim()}
                >
                  {reviewInProgress ? 'Saving...' : 'Reject'}
                </button>
              </div>
              {reviewError && <p className="cedros-admin-error-inline">{reviewError}</p>}
            </div>
          )}
        </>
      ) : (
        accreditationData && (
          <div className="cedros-admin-empty-message">No accreditation submissions found.</div>
        )
      )}
    </div>
  );
}
